create extension if not exists pg_trgm;
create table if not exists public.order_headers (id bigint generated by default as identity primary key, customer_name text not null, customer_email text not null, customer_phone text, total_amount numeric(14,2) not null default 0, currency text not null default 'VND', status text not null default 'new' check(status in('new','confirmed','processing','completed','cancelled')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.order_items (id bigint generated by default as identity primary key, order_id bigint not null references public.order_headers(id) on delete cascade, product_id bigint, product_name text not null, quantity integer not null check(quantity>0), unit_price numeric(14,2) not null check(unit_price>=0));
alter table public.order_headers enable row level security;
alter table public.order_items enable row level security;
create or replace function public.search_site_content(search_query text, search_locale text default 'vi', result_limit integer default 50)
returns table(id bigint,type text,title text,excerpt text,date text,image text,slug text) language sql stable security invoker set search_path=public as $$
select * from (
 select id,'news',case when search_locale='en' then title_en else title end,case when search_locale='en' then excerpt_en else excerpt end,date::text,image,null::text from content_news where (search_locale<>'en' or title_en is not null) and concat_ws(' ',title,excerpt,title_en,excerpt_en) ilike '%'||search_query||'%'
 union all select id,'products',case when search_locale='en' then title_en else title end,case when search_locale='en' then description_en else description end,date::text,image,slug from content_products where (search_locale<>'en' or title_en is not null) and concat_ws(' ',title,description,title_en,description_en) ilike '%'||search_query||'%'
 union all select id,'projects',case when search_locale='en' then title_en else title end,case when search_locale='en' then description_en else description end,year,image,null::text from content_projects where (search_locale<>'en' or title_en is not null) and concat_ws(' ',title,description,title_en,description_en) ilike '%'||search_query||'%'
) r limit greatest(1,least(result_limit,100)); $$;
grant execute on function public.search_site_content(text,text,integer) to anon,authenticated;
